// Mirrors protocol.RuntimeInfo. RuntimeInfo 是运行时环境的完整状态，也是唯一的对外形状。 它同时是 RuntimeStatus()（纯读，不联网）的返回值和 EventRuntimes 的载荷。
export interface RuntimeInfo {
  platform: string;
  packs: RuntimePack[] | null;
  fetched: boolean;
  error: string;
}

// Mirrors protocol.RuntimeManifest. RuntimeManifest 是清单响应：这个平台上有哪些包可装。 GET {Bridge}/api/app/runtimes?product=xrun&platform=windows/amd64 为什么这一份 wire 类型是公开的、而版本更新那份（releaseWire）是私有的：清单 在本仓有**两个**消费者——客户端解析它，tools/runtimepacks 生成它。两处各写一遍 结构体，迟早有一天字段名对不上，而那种错只在装机之后才显形。放在这里，两边 编译期就绑住了。
export interface RuntimeManifest {
  platform: string;
  packs: RuntimeManifestPack[] | null;
}

// Mirrors protocol.RuntimeManifestPack. RuntimeManifestPack 是清单里的一个包。 它刻意**不含**可执行文件路径、PATH 目录、环境变量：那些是"本机要执行什么"， 由客户端按 id 与平台自己决定（见 desktop/runtimepack.go）。清单能改的只有 "下哪个文件"，不能改"跑哪个文件"。
export interface RuntimeManifestPack {
  id: string;
  version: string;
  url: string;
  sha256: string;
  size: number;
  notes: string;
}

// Mirrors protocol.RuntimePack. RuntimePack 是一个运行时包此刻的全部状态：托管包装没装、系统里有没有、能不能用。
export interface RuntimePack {
  id: RuntimePackId;
  label: string;
  summary: string;
  stage: RuntimeStage;
  version: string;
  available: string;
  size: number;
  received: number;
  error: string;
  systemPath: string;
  systemVersion: string;
  systemUsable: boolean;
  minVersion: string;
  active: string;
  needsAuthorize: boolean;
}

// Mirrors protocol.SaveCustomModelRequest. SaveCustomModelRequest 新增或修改一个自定义模型。编辑时 OriginalName 定位旧 记录；APIKey 留空表示保留旧密钥，ClearAPIKey 才显式清除，两者不能同时使用。
export interface SaveCustomModelRequest {
  supportsImages?: boolean;
  clearImageSupport?: boolean;
  originalName?: string;
  name: string;
  provider?: string;
  model: string;
  baseURL: string;
  authMode?: string;
  apiKey?: string;
  clearAPIKey?: boolean;
}

// Mirrors protocol.SaveImageGenerationEditRequest. SaveImageGenerationEditRequest 把画板合成的 PNG 存为同一 generation 目录下的新副本。 SourcePath 必须是本会话工作区 生成图片/<generationId>/ 下已有图片（含 edited-*.png）。 SourceReference 必填：宿主在同一来源会话操作内核对引用、session、generation 与路径。
export interface SaveImageGenerationEditRequest {
  sessionId: string;
  sourcePath: string;
  sourceReference: string;
  pngBase64: string;
}

// Mirrors protocol.SaveImageGenerationSettingsRequest. SaveImageGenerationSettingsRequest 替换某一作用域的默认。DefaultModel 为 nil 表示清除。不带 Bridge／账号字段：宿主从当前身份推导作用域，并拒绝过期 ScopeID。
export interface SaveImageGenerationSettingsRequest {
  tenantId: string;
  scopeId: string;
  expectedRevision: number;
  defaultModel?: ModelReference;
  defaultSize: string;
}

// Mirrors protocol.SaveMailAccountRequest. SaveMailAccountRequest 保存当前表单。Password 留空保留旧值；ClearPassword 才清空。 ConfigFingerprint 必须来自同配置的 TestMailConnection 成功结果。
export interface SaveMailAccountRequest {
  address: string;
  displayName: string;
  version: string;
  password?: string;
  clearPassword?: boolean;
  configFingerprint: string;
  expectedRevision: number;
  enabled: boolean;
}

// Mirrors protocol.SaveMailContactRequest. SaveMailContactRequest 新建或 CAS 更新联系人。
export interface SaveMailContactRequest {
  id?: string;
  name: string;
  emails: string[] | null;
  expectedRevision: number;
}

// Mirrors protocol.SaveMailDraftRequest. SaveMailDraftRequest 保存用户修订（CAS）。
export interface SaveMailDraftRequest {
  id: string;
  expectedRevision: number;
  accountId: string;
  subject: string;
  bodyMarkdown: string;
  to: MailAddressView[] | null;
  cc: MailAddressView[] | null;
  bcc: MailAddressView[] | null;
  sendMode: string;
  dispatchMode: string;
  scheduledLocal?: string;
  timeZone?: string;
}

// Mirrors protocol.SaveModelContextSettingsRequest. SaveModelContextSettingsRequest replaces or clears one model preference.
export interface SaveModelContextSettingsRequest {
  model: ModelReference;
  overrides: ModelContextOverride;
}

// Mirrors protocol.SaveSettingsRequest. SaveSettingsRequest 只包含设置页拥有的字段，连接与租户由专用命令管理。
export interface SaveSettingsRequest {
  sessionId?: string;
  permissionMode: string;
  harmJudgeModel: string;
  harmJudgeVotes: number;
  skipLogin?: boolean;
}

// Mirrors protocol.SaveVisionSettingsRequest. SaveVisionSettingsRequest changes only the default destination, not a stale snapshot of the catalog or credentials.
export interface SaveVisionSettingsRequest {
  disabled?: boolean;
  defaultModel?: ModelReference;
}

// Mirrors protocol.SecretStorage. SecretStorage 报告本机能不能安全保存登录状态。 凭据保护在取不到系统钥匙串时**故意不落盘**（理由见 desktop/secret_keyring.go）。 这个取舍是对的，但此前它是全静默的——用户看到的只有"怎么每次都要重新登录"， 而真正的原因可能只是少装了一个包。这三个字段就是为了把那句话说出来。
export interface SecretStorage {
  ok: boolean;
  reason?: string;
  fix?: string;
}

// Mirrors protocol.SendMailTestToSelfRequest. SendMailTestToSelfRequest 向已保存账号自身发固定测试信；无收件人字段。
export interface SendMailTestToSelfRequest {
  expectedRevision: number;
  clientRequestId?: string;
}

// Mirrors protocol.SessionAutomationRunsRequest. SessionAutomationRunsRequest lists runs linked to one workspace session.
export interface SessionAutomationRunsRequest {
  context: AutomationContext;
  workspace: string;
  sessionId: string;
  cursor?: string;
  limit?: number;
  ownerScope?: string;
}

// Mirrors protocol.SessionInfo. SessionInfo is the display state returned when a session starts and by Status.
export interface SessionInfo {
  sessionId: string;
  model: string;
  cwd: string;
  permissionMode: string;
  planMode: boolean;
  reasoningScenario: string;
  thinkingEffort: string;
  maxContextTokens: number;
  inputPricePerMTok: number;
  outputPricePerMTok: number;
  pricingSource: string;
  previewBaseURL: string;
}

// Mirrors protocol.SessionRenamed. SessionRenamed announces a session's freshly generated title.
export interface SessionRenamed {
  id: string;
  title: string;
}

// Mirrors protocol.SessionSummary. SessionSummary describes a saved session for the sidebar's recent list.
export interface SessionSummary {
  kind?: string;
  id: string;
  title: string;
  when: string;
  turns: number;
  automation?: AutomationOrigin;
}

// Mirrors protocol.SetAutomationTaskPausedRequest. SetAutomationTaskPausedRequest sets the paused bit.
export interface SetAutomationTaskPausedRequest {
  context: AutomationContext;
  taskId: string;
  expectedRevision: number;
  paused: boolean;
  ownerScope?: string;
}

// Mirrors protocol.SetPlatformImageCapabilityRequest. SetPlatformImageCapabilityRequest updates one override; nil removes it.
export interface SetPlatformImageCapabilityRequest {
  model: ModelReference;
  supportsImages?: boolean;
}

// Mirrors protocol.SettingsView. SettingsView 是脱敏只读视图，不包含凭据或存储记录。
export interface SettingsView {
  cwd: string;
  provider: string;
  model: string;
  customModelName?: string;
  tenantId: string;
  baseURL: string;
  permissionMode: string;
  reasoningScenario: string;
  thinkingEffort: string;
  harmJudgeModel: string;
  harmJudgeVotes: number;
  recentWorkspaces?: string[] | null;
  webProxy?: string;
  skipLogin?: boolean;
  contextAudit?: boolean;
}

// Mirrors protocol.SkillInfo. SkillInfo is one project skill for the UI's skill manager.
export interface SkillInfo {
  name: string;
  displayName: string;
  displayDescription: string;
  description: string;
  body: string;
  source: string;
  path: string;
  editable: boolean;
  disabledUser: boolean;
  disabledProject: boolean;
}

// Mirrors protocol.SkillInstallProgress. SkillInstallProgress 是一次安装的实时进度。 它报的是**真的发生了什么**，不是按定时器推的假进度：Stage 由各步骤自己发， Received/Total 来自 HTTP 响应体的实际字节数与 Content-Length。假进度条在快的 时候显得慢、在卡住的时候还在动，等于把唯一能判断"是不是死了"的信号也抹掉。
export interface SkillInstallProgress {
  id: number;
  name: string;
  stage: string;
  received: number;
  total: number;
}

// Mirrors protocol.SkillList. SkillList is the skill manager's view: loaded skills plus load problems.
export interface SkillList {
  skills: SkillInfo[] | null;
  problems: SkillProblem[] | null;
}

// Mirrors protocol.SkillLoad. SkillLoad is what the desktop's Skill tool attaches to its progress event's `data` when the model loads a skill, so the chat can render a card naming what was loaded instead of a bare "加载技能" row.
export interface SkillLoad {
  name: string;
  description: string;
  source: string;
  dir: string;
  truncated?: boolean;
}

// Mirrors protocol.SkillMarketPage. SkillMarketPage 是市场页一次要画的全部东西。 Categories 由这一批技能的 category 去重得来，而不是另开一个接口：上游没有分类 接口，分类本来就只是技能表里的一列，从数据里长出来的页签永远和内容对得上。
export interface SkillMarketPage {
  skills: MarketSkill[] | null;
  categories: string[] | null;
  total: number;
  fetchedAt: string;
}

// Mirrors protocol.SkillProblem. SkillProblem reports a skill directory that failed to load.
export interface SkillProblem {
  dir: string;
  reason: string;
}

// Mirrors protocol.SkillSaveRequest. SkillSaveRequest creates or updates a skill.
export interface SkillSaveRequest {
  originalName: string;
  name: string;
  displayName: string;
  displayDescription: string;
  description: string;
  body: string;
  scope: string;
}

// Mirrors protocol.StartRecordingRequest. StartRecordingRequest 开一场录音。空字段一律回落到 RecorderSettings 里存的值。
export interface StartRecordingRequest {
  title: string;
  lang: string;
  micDeviceId: string;
  sysDeviceId: string;
}

// Mirrors protocol.StartSessionRequest. StartSessionRequest opens a session for a workspace.
export interface StartSessionRequest {
  cwd: string;
  provider: string;
  model: string;
  customModelName?: string;
  tenantId: string;
  baseURL: string;
  apiKey: string;
  authToken: string;
  permissionMode: string;
  reasoningScenario: string;
  thinkingEffort: string;
  harmJudgeModel: string;
  harmJudgeVotes: number;
  resume: string;
  continue: boolean;
}

// Mirrors protocol.SubmitQuestionRequest. SubmitQuestionRequest supports ordinary input and a prepared retry branch.
export interface SubmitQuestionRequest {
  sessionId: string;
  text: string;
  imagePaths: string[] | null;
  source?: QuestionReference;
  originalImages: number[] | null;
  allowSteering: boolean;
}

// Mirrors protocol.TestMailConnectionRequest. TestMailConnectionRequest 使用当前表单值探测 SMTP，不落盘、不发信。
export interface TestMailConnectionRequest {
  address: string;
  password: string;
  version: string;
}

// Mirrors protocol.ToolEvent. ToolEvent is the wire form of one tool-lifecycle update.
export interface ToolEvent {
  type: ToolEventType;
  toolName?: string;
  toolUseID?: string;
  parentToolUseID?: string;
  agentName?: string;
  input?: unknown;
  message?: string;
  data?: unknown;
  files?: FileReference[] | null;
  filesTotal?: number;
  output?: OutputLine[] | null;
  outputTotal?: number;
  outputTruncated?: boolean;
  image?: ResultImage;
  inputTokens?: number;
  outputTokens?: number;
  durationMs?: number;
}

// Mirrors protocol.ToolInfo. ToolInfo is a tool's name and description for the @-mention picker.
export interface ToolInfo {
  name: string;
  description: string;
  source: string;
  server?: string;
  concurrencySafe: boolean;
  toggleable: boolean;
  disabledUser: boolean;
  disabledProject: boolean;
}

// Mirrors protocol.TurnEnd. TurnEnd summarizes a completed turn.
export interface TurnEnd {
  text: string;
  stopReason: string;
  iterations: number;
  toolResultCount: number;
  inputTokens: number;
  outputTokens: number;
  contextTokens: number;
  contextTokensSaved?: number;
  stopped: boolean;
  durationMs?: number;
}

// Mirrors protocol.TurnError. TurnError reports a failed or interrupted turn.
export interface TurnError {
  error: string;
}

// Mirrors protocol.TurnQueued. TurnQueued announces that a submitted turn is waiting for a concurrency slot.
export interface TurnQueued {
}

// Mirrors protocol.UpdateAutomationTaskRequest. UpdateAutomationTaskRequest replaces the editable fields.
export interface UpdateAutomationTaskRequest {
  context: AutomationContext;
  taskId: string;
  expectedRevision: number;
  draft: AutomationTaskDraft;
  ownerScope?: string;
}

// Mirrors protocol.UpdateInfo. UpdateInfo 是更新器的完整状态，也是唯一的对外形状。 它同时是 UpdateStatus()（纯读，不联网）的返回值和 EventUpdate 的载荷：读一次拿到 的东西和后续推送过来的东西是同一种，前端不必为「初始态」和「更新态」写两套解析。
export interface UpdateInfo {
  current: string;
  stage: UpdateStage;
  latest: string;
  notes: string;
  publishedAt: string;
  size: number;
  received: number;
  checkedAt: string;
  error: string;
  installError: string;
  canInstall: boolean;
  file: string;
  autoRestart: boolean;
  installHint: string;
}

// Mirrors protocol.UsageBucket. UsageBucket 是趋势里的一个时间桶（首尾可能是被裁剪的部分桶）。coverage 取 known（已覆盖，没有记录就是真 0）/ gap（有证据的采集缺口）/ unknown（覆盖未知）。
export interface UsageBucket {
  startAt: string;
  endAt: string;
  requestCount: string;
  inputTokens: string | null;
  outputTokens: string | null;
  totalTokens: string | null;
  cacheHitTokens: string | null;
  cacheEligibleInputTokens: string | null;
  coverage: string;
}

// Mirrors protocol.UsageCapabilities. UsageCapabilities 声明本次数据能可靠支持哪些维度；本机记录支持请求状态，TTFT 未采集。
export interface UsageCapabilities {
  providerBreakdown: boolean;
  cacheMetrics: boolean;
  requestStatus: boolean;
  ttft: boolean;
}

// Mirrors protocol.UsageCoverageGap. UsageCoverageGap 是一段有证据的采集缺口。
export interface UsageCoverageGap {
  startAt: string;
  endAt: string;
  reason?: string;
}

// Mirrors protocol.UsageDimensionRow. UsageDimensionRow 是一个模型或供应商的汇总；供应商无法确定时归入 unknown 分组。
export interface UsageDimensionRow {
  id: string;
  name: string;
  totals: UsageTotals;
}

// Mirrors protocol.UsageDimensionsPage. UsageDimensionsPage 是一页分组汇总，按请求数降序、ID 稳定排序。
export interface UsageDimensionsPage {
  items: UsageDimensionRow[] | null;
  groupBy: string;
  page: number;
  pageSize: number;
  totalCount: string;
  hasMore: boolean;
  effectiveRange: UsageEffectiveRange;
  queryKey: string;
}

// Mirrors protocol.UsageDimensionsQuery. UsageDimensionsQuery 读取按模型或供应商分组的汇总（groupBy = model / provider）。 pageSize 只能是 50/100，page 从 1 开始。
export interface UsageDimensionsQuery {
  query: ResolvedUsageQuery;
  groupBy: string;
  search?: string;
  page: number;
  pageSize: number;
}

// Mirrors protocol.UsageEffectiveRange. UsageEffectiveRange 是桌面端为一次查询固定下来的半开区间 [startAt, endAt)。
export interface UsageEffectiveRange {
  startAt: string;
  endAt: string;
  timezone: string;
}

// Mirrors protocol.UsageOverview. UsageOverview 是同一次本机快照读取到的汇总、趋势与质量。dataAsOf 是本机读取时刻； local_platform 来源不使用 replicaLagSeconds。
export interface UsageOverview {
  scopeId: string;
  snapshotSeq?: string;
  collectionStartedAt?: string;
  storageStatus?: string;
  statusCounts?: UsageStatusCounts;
  queryKey: string;
  effectiveRange: UsageEffectiveRange;
  dataAsOf: string;
  summary: UsageTotals;
  trend: UsageBucket[] | null;
  capabilities: UsageCapabilities;
  empty: boolean;
  coverageStart: string | null;
  coverageGaps: UsageCoverageGap[] | null;
  coverageStatus: string;
  coverageMessage?: string;
  sourceKind?: string;
  replicaLagSeconds: number | null;
  consistency?: string;
  mappingVersion?: string;
}

// Mirrors protocol.UsageQuality. UsageQuality 描述一组统计的口径覆盖：tokenCoverage / cacheCoverage 取 complete / partial / none；containsEstimates 表示合计含本地近似缓存（非供应商精确命中）； legacy 标记说明合计里含无法确认来源的历史口径。
export interface UsageQuality {
  tokenCoverage: string;
  cacheCoverage: string;
  containsEstimates: boolean;
  containsLegacyUnknown: boolean;
  containsLegacyInferredCache: boolean;
  invalidRecordCount: string;
}

// Mirrors protocol.UsageQuery. UsageQuery 是总览查询。range 取 today / last24h / last7d / last14d / last30d / all / custom；custom 时 startAt 必填，endAt 与 followNow 二选一（followNow 只是 页面偏好：每次刷新由桌面端固定成读取时刻）。timezone 固定 Asia/Shanghai。
export interface UsageQuery {
  tenantId: string;
  range: string;
  startAt?: string;
  endAt?: string;
  followNow: boolean;
  timezone: string;
  providerId?: string;
  model?: string;
}

// Mirrors protocol.UsageRequestRow. UsageRequestRow 是一条已入账的消费记录，只有计量与口径，没有正文或成本。 meterKind 不是 tokens 时 Token 各列为 null，用量见 usageQuantity + usageUnit。
export interface UsageRequestRow {
  id: string;
  status?: string;
  recordedAt: string;
  startedAt: string | null;
  model: string;
  providerId: string | null;
  providerName: string | null;
  meterKind: string;
  usageQuantity: string | null;
  usageUnit: string | null;
  inputTokens: string | null;
  outputTokens: string | null;
  cacheHitTokens: string | null;
  cacheMissTokens: string | null;
  reasoningTokens: string | null;
  durationMs: number | null;
  quality: UsageRowQuality;
}

// Mirrors protocol.UsageRequestsPage. UsageRequestsPage 是一页请求日志；totalCount 与 nextCursor 绑定同一个本机快照水位、范围与筛选。
export interface UsageRequestsPage {
  items: UsageRequestRow[] | null;
  totalCount: string;
  pageSize: number;
  nextCursor?: string;
  hasMore: boolean;
  effectiveRange: UsageEffectiveRange;
  queryKey: string;
}

// Mirrors protocol.UsageRequestsQuery. UsageRequestsQuery 读取一页请求日志。第一页不带 cursor；pageSize 只能是 20/50/100。
export interface UsageRequestsQuery {
  query: ResolvedUsageQuery;
  cursor?: string;
  pageSize: number;
}

// Mirrors protocol.UsageRowQuality. UsageRowQuality 是单条记录各项用量的来源口径（reported / estimated / derived / legacyUnknown / legacyInferred / unavailable）。
export interface UsageRowQuality {
  tokenSource: string;
  cacheSource: string;
  reasoningSource: string;
}

// Mirrors protocol.UsageStatusCounts. UsageStatusCounts 保留在途与五种终态的独立计数，pending 不进入已完成请求数。
export interface UsageStatusCounts {
  pending: string;
  succeeded: string;
  failed: string;
  cancelled: string;
  unknown: string;
  saveFailed: string;
}

// Mirrors protocol.UsageTotals. UsageTotals 是一组记录的聚合。tokenRequestCount 是全部已结束的 LLM/识图调用数， sampleCount 是其中有可信数值的样本数；totalTokens 汇总所有已知输入与输出。 totalTokens = inputTokens + outputTokens（缓存是输入 子集、思考是输出子集，都不再相加）；缓存三项只统计可信缓存子集，命中率是 SUM(命中)/SUM(可信输入)。
export interface UsageTotals {
  requestCount: string;
  tokenRequestCount: string;
  inputTokenSampleCount?: string;
  outputTokenSampleCount?: string;
  totalTokenSampleCount?: string;
  inputTokens: string | null;
  outputTokens: string | null;
  totalTokens: string | null;
  cacheHitTokens: string | null;
  cacheMissTokens: string | null;
  cacheEligibleInputTokens: string | null;
  cacheHitRate: number | null;
  cacheKnownRequestCount: string;
  cacheEligibleRequestCount: string;
  reasoningTokens: string | null;
  durationSampleCount: string;
  averageDurationMs: number | null;
  quality: UsageQuality;
}

// Mirrors protocol.VisionSettings. VisionSettings configures the fixed destination for automatic image analysis.
export interface VisionSettings {
  disabled?: boolean;
  bridge?: string;
  defaultModel?: ModelReference;
  platformCapabilities: PlatformImageCapability[] | null;
}

// Mirrors protocol.Warning. Warning is a non-fatal diagnostic surfaced to the UI.
export interface Warning {
  message: string;
}

// Mirrors protocol.WindowCapabilitiesView. WindowCapabilitiesView 是宿主窗口能力只读快照；不查自动化任务库。
export interface WindowCapabilitiesView {
  available: boolean;
  backgroundSupported: boolean;
}
